import math
def control(obs):
    h=math.radians(obs['hitch_deg'])
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        ox,oy=cam['origin']; groups=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
            u=-x*math.cos(h)+y*math.sin(h); w=x*math.sin(h)+y*math.cos(h)
            if u>0.2: groups[0 if w<0 else 1].append((u,w))
        def interp(points,u):
            points=sorted(points)
            if not points:return None
            for (a,b),(c,d) in zip(points,points[1:]):
                if a<=u<=c:return b+(d-b)*(u-a)/max(.001,c-a)
            return min(points,key=lambda p:abs(p[0]-u))[1]
        u=4.0
        a=interp(groups[0],u); b=interp(groups[1],u)
        if a is not None and b is not None:
            mid=(a+b)/2
            desired=max(-27,min(27,math.degrees(math.atan(7.3*mid/(u*u)))))
    steer=max(-34,min(34,2.0*obs['hitch_deg']-1.3*desired))
    return steer,-0.65,-23

