import math
start=None
last=-1
def control(o):
 global start,last
 if start is None:start=o['t']
 p=int((o['t']-start)/1.6)
 look=64 if p%2==0 else -64
 if o['head']['settled'] and abs(o['head']['gaze_deg']-look)<2 and p!=last:
  last=p
  for name in ('left_mirror','right_mirror'):
   if name in o['views']:
    v=o['views'][name]; x,y=v['origin']
    pts=[(round(x+d*math.cos(math.radians(b)),1),round(y+d*math.sin(math.radians(b)),1)) for b,d in v['walls']]
    print(name,'progress',o['progress']['covered'],'points',pts)
 return (max(-35,min(35,2*o['hitch_deg'])),-0.4,look)

