import math
rails={}
prev=None
last=-10
def control(o):
 global prev,last,rails
 t=o['t']; h=o['hitch_deg']; dt=o['dt']
 if prev is not None:
  v=o['motion']['v_mps']; a=math.radians(o['steer_deg']); da=v*math.tan(a)/2.5*dt; dx=v*dt
  c=math.cos(da); s=math.sin(da)
  for k,(stamp,pts) in list(rails.items()):
   rails[k]=(stamp,[(c*(x-dx)+s*y,-s*(x-dx)+c*y) for x,y in pts])
 prev=t
 p=int(t/1.8); look=64 if p%2==0 else -64
 for name,sgn in [('left_mirror',1),('right_mirror',-1)]:
  if name in o['views']:
   view=o['views'][name]; ox,oy=view['origin']; pts=[]
   for b,d in view['walls']:
    if 150<sgn*b<179 and d<16:
     a=math.radians(b); pts.append((ox+d*math.cos(a),oy+d*math.sin(a)))
   if pts:rails[name]=(t,pts)
 rx,ry=o['rig']['trailer_rear']; tx=rx-3.5
 ys=[]
 for name in ('left_mirror','right_mirror'):
  if name in rails and t-rails[name][0]<6:
   pts=rails[name][1]; near=[(x,y) for x,y in pts if abs(x-tx)<1.4]
   if near:
    weights=[math.exp(-((x-tx)/0.8)**2) for x,y in near]
    ys.append(sum(w*y for w,(x,y) in zip(weights,near))/sum(weights))
 desired=0
 if len(ys)==2:
  ty=sum(ys)/2; beta=math.atan2(ty-ry,rx-tx); alpha=beta-math.radians(h)
  desired=math.degrees(math.atan(2*3.6*math.sin(alpha)/3.5))
  desired=max(-24,min(24,desired))
 else:
  desired=h*0.7
 steer=max(-40,min(40,0.51*h+1.6*(h-desired)))
 if t-last>4:
  last=t; print('TRACK',round(o['progress']['covered'],1),'h',round(h,1),'desired',round(desired,1),'rail_y',ys)
 return (steer,-0.45,look)

