import math
last=0.0
def control(o):
 global last
 h=o['hitch_deg']; th=math.radians(-h); c=math.cos(th); s=math.sin(th)
 cam=o.get('views',{}).get('camera')
 desired=last
 if cam:
  sides=[[],[]]
  for b,d in cam.get('walls',[]):
   b=math.radians(b); dx=d*math.cos(b); dy=d*math.sin(b)
   u=-dx*c-dy*s; w=-dx*s+dy*c
   if u>1 and abs(w)>1.5: sides[0 if w>0 else 1].append((u,w))
  vals=[]
  for U in [5,7,9,11]:
   ws=[]
   for side in sides:
    near=sorted(side,key=lambda p:abs(p[0]-U))[:2]
    if near and abs(near[0][0]-U)<3:
     ws.append(sum(p[1]/(0.5+abs(p[0]-U)) for p in near)/sum(1/(0.5+abs(p[0]-U)) for p in near))
   if len(ws)==2: vals.append((U,(ws[0]+ws[1])/2))
  if vals:
   U,w=vals[-1]; desired=max(-30,min(30,math.degrees(math.atan(20.4*w/(U*U)))))
   last=0.9*last+0.1*desired
 steer=max(-36,min(36,0.38*h+1.5*(h-last)))
 return (steer,-0.85,-41)

